  const w2y = Math.cos((y+w1y)*0.014-t*0.2)*9 + Math.sin((x+w1x)*0.011+t*0.17)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.07, 2.1, 1.0],
    [340+Math.cos(t*0.45)*100, 150+Math.sin(t*0.6)*60, 0.09, 1.8, 0.8],
    [240+Math.sin(t*0.28+2)*150, 100+Math.cos(t*0.42+1)*100, 0.055, 2.4, 1.2],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*70, 0.11, 1.6, 0.7],
    [380+Math.sin(t*0.38+4)*100, 50+Math.cos(t*0.75+2)*80, 0.065, 2.7, 1.1],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*90, 0.085, 2.0, 0.9],
    [60+Math.sin(t*0.6+3)*70, 130+Math.cos(t*0.5+4)*50, 0.1, 1.4, 0.6],
    [420+Math.cos(t*0.4+2)*80, 180+Math.sin(t*0.65+1)*60, 0.075, 2.3, 1.0]
  ];
  let aS=0, iS=0, cross=0;
  for(let j=0;j<src.length;j++){
    const [sX,sY,f,sp,w]=src[j];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    for(let k=j+1;k<src.length;k++){
      const [sX2,sY2]=src[k];
      const mx=(sX+sX2)/2, my=(sY+sY2)/2;
      const dm=Math.sqrt((sx-mx)**2+(sy-my)**2);
      cross+=Math.sin(dm*0.12-t*1.5+j*0.8)*0.15;
    }
  }
  const n=src.length, act=aS/n, inh=iS/n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.9)+Math.sin(sx*0.028-sy*0.038+t*1.2))/2
    +Math.sin((sx+sy)*0.11+t*2.8)*0.18+Math.sin((sx-sy)*0.09-t*2.2)*0.18
    +Math.sin(sx*0.06+sy*0.04-t*0.7)*0.12;
