      const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md){m2=md;md=d}else if(d<m2){m2=d}
    }
    return Math.sin((m2-md)*0.3-t*1.2)*0.2;
  };
  const reaction=Math.tanh((act-inh*0.65+bg*0.3+spiral+cross+voro())*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.45+Math.sin(sx*0.08-t*0.6)*Math.cos(sy*0.1+t*0.4)*0.3)*1.4)*0.25;
  const pulse=0.92+Math.sin(t*0.4)*0.08;
  const blend=(reaction*0.7+cell*0.3)*pulse;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[10,45,85],[12,85,105],[18,130,120],[65,155,110],[160,170,80],[210,185,60],[225,140,55],[215,95,60],[185,60,55],[140,35,55],[85,20,50],[40,15,45],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.78+Math.sin(reaction*Math.PI)*0.22;
  const edge=Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.18:1.0;
  const glow=Math.max(0,reaction-0.3)*0.25;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*40)|0)
  ];
}
